parameters.jsCode:
// Récupérer la sortie du Script Writer
let output = $input.item.json.output;

// Nettoyer le texte (enlever les balises markdown et espaces)
output = output.trim();
output = output.replace(/```json\n?/g, '');
output = output.replace(/```\n?/g, '');
output = output.trim();

// Parser le JSON
let parsed;
try {
  parsed = JSON.parse(output);
} catch (error) {
  // Si le parsing échoue, créer un objet par défaut
  console.error('Erreur de parsing JSON:', error);

  // Essayer d'extraire le titre et le script manuellement
  const titleMatch = output.match(/"title"\s*:\s*"([^"]*)"/);
  const scriptMatch = output.match(/"script"\s*:\s*"([^"]*)"/);

  parsed = {
    title: titleMatch ? titleMatch[1] : "AI Video " + new Date().toISOString().slice(0,10),
    script: scriptMatch ? scriptMatch[1] : output.substring(0, 200)
  };
}

// Retourner l'objet parsé
return {
  json: {
    title: parsed.title || "AI Video",
    script: parsed.script || parsed.output || output
  }
};

